// Check condition
function checkCondition(type, value, targetValue) {
  let isTopLevel = arguments.length > 3 && arguments[3] !== undefined ? arguments[3] : true;
  if (type === 'ne' && value === '') {
    return true;
  } else if (type === 'eq' && targetValue == value) {
    return true;
  } else if (type === 'neq' && targetValue != value) {
    return true;
  } else if (type === 'gt' && !Number.isNaN(parseInt(targetValue)) && !Number.isNaN(parseInt(value)) && parseInt(targetValue) > parseInt(value)) {
    return true;
  } else if (type === 'lt' && !Number.isNaN(parseInt(targetValue)) && !Number.isNaN(parseInt(value)) && parseInt(targetValue) < parseInt(value)) {
    return true;
  } else if (type === 'egt' && !Number.isNaN(parseInt(targetValue)) && !Number.isNaN(parseInt(value)) && parseInt(targetValue) >= parseInt(value)) {
    return true;
  } else if (type === 'elt' && !Number.isNaN(parseInt(targetValue)) && !Number.isNaN(parseInt(value)) && parseInt(targetValue) <= parseInt(value)) {
    return true;
  } else if (type === 'isTopLevel' && value == isTopLevel) {
    return true;
  } else {
    return false;
  }
}

/**
* Create context and pass it to createTableFromContext
* @param {object} dialog
*/
function createDisplayGroupMembersTable(dialog) {
  const control = $(dialog).find('.controlDiv');
  const context = {
    tableName: '#displaysGroupsMembersTable',
    columns: [{
      data: 'displayGroupId',
      responsivePriority: 2
    }, {
      data: 'displayGroup',
      responsivePriority: 2
    }],
    members: control.data().members.displayGroups,
    extra: dialog.data().extra.displayGroupsAssigned,
    id: 'displayGroupId',
    type: 'displayGroup',
    getUrl: control.data().displayGroupsGetUrl
  };
  createTableFromContext(dialog, context);
}

/**
* Create context and pass it to createTableFromContext
* @param {object} dialog
*/
function createDisplayMembersTable(dialog) {
  const control = $(dialog).find('.controlDiv');
  const context = {
    tableName: '#displaysMembersTable',
    columns: [{
      data: 'displayId',
      responsivePriority: 2
    }, {
      data: 'display',
      responsivePriority: 2
    }, {
      data: 'mediaInventoryStatus',
      responsivePriority: 2,
      render: function (data, type, row) {
        if (type != 'display') {
          return data;
        }
        let icon = '';
        if (data == 1) {
          icon = 'fa-check';
        } else if (data == 0) {
          icon = 'fa-times';
        } else {
          icon = 'fa-cloud-download';
        }
        return '<span class=\'fa ' + icon + '\'></span>';
      }
    }, {
      data: 'loggedIn',
      render: dataTableTickCrossColumn,
      responsivePriority: 3
    }, {
      name: 'clientSort',
      responsivePriority: 3,
      data: function (data) {
        return data.clientType + ' ' + data.clientVersion + '-' + data.clientCode;
      },
      visible: false
    }],
    members: control.data().members.displays,
    extra: dialog.data().extra.displaysAssigned,
    id: 'displayId',
    type: 'display',
    getUrl: control.data().displayGetUrl
  };
  createTableFromContext(dialog, context);
}

