/**
* Set the checkbox state based on the adjacent features
* @param triggerElement
*/
function setFeatureGroupCheckboxState(triggerElement) {
  // collect up the checkboxes belonging to the same group
  const $featureGroup = triggerElement.closest('tbody.feature-group');
  const countChecked = $featureGroup.find('input[name=\'features[]\']:checked').length;
  const countTotal = $featureGroup.find('input[name=\'features[]\']').length;
  setCheckboxState(countChecked, countTotal, $featureGroup, '.feature-select-all');

  // collect up the inherit checkboxes belonging to the same group
  const countInheritChecked = $featureGroup.find('input.inherit-group:checked').length;
  const countInheritTotal = $featureGroup.find('input.inherit-group').length;
  setCheckboxState(countInheritChecked, countInheritTotal, $featureGroup, '.inherit-group-all');
}

/**
* Set checkbox state helper function
* @param count
* @param countTotal
* @param $selector
* @param checkboxClass
*/
function setCheckboxState(count, countTotal, $selector, checkboxClass) {
  if (count <= 0) {
    $selector.find(checkboxClass).prop('checked', false).prop('indeterminate', false);
  } else if (count === countTotal) {
    $selector.find(checkboxClass).prop('checked', true).prop('indeterminate', false);
  } else {
    $selector.find(checkboxClass).prop('checked', false).prop('indeterminate', true);
  }
}

